/// Look up a specialised shader for this draw mode.
#[inline]
pub fn lookup(dm0: u32, dm1: u32, cm: u32) -> Option<ShaderFn> {
    SHADERS
        .binary_search_by_key(&(dm0, dm1, cm), |&(k, _)| k)
        .ok()
        .map(|i| SHADERS[i].1)
}
